//! Who may call the JSON resources generated by `forge generate resource`
//! (and `forge generate scaffold`) under `/v1/<plural>`.
//!
//! Every generated handler asks an access policy before it reads or changes
//! anything, with the permission of the action (`<plural>:read` or
//! `<plural>:write`). Access is **deny by default**: the generator wires
//! [`DenyAll`] unless the application can resolve bearer tokens, so a new
//! resource is never public by accident.
//!
//! - Tenant-scoped resources use an [`ApiTenantAccess`].
//!   [`BearerTenantAccess`] authenticates the `Authorization: Bearer` token
//!   that `POST /auth/login` issued (`forge new --api-auth`), takes the
//!   tenant the token was issued for, loads the principal's membership in it
//!   and evaluates the RBAC policy, producing an authorized
//!   [`TenantContext`]. Only the header is read: cookies, query parameters
//!   and `X-Tenant-*` headers never name a tenant or stand in for a token.
//! - Global resources use an [`ApiGlobalAccess`]. Their rows are shared by
//!   every tenant, so tenant roles cannot authorize them: implement
//!   [`ApiGlobalAccess`] with your own rule (for example operators) and
//!   replace [`DenyAll`] in `src/bootstrap/mod.rs`.
//!
//! Refusals are JSON error reports with Forge-Go's codes
//! (`forge::web::bearer_refusal`): `401 credentials_required` without a
//! token, `401 credentials_invalid` for a malformed, unknown, expired, idle
//! or revoked one, `403 permission_denied`, `503` when a store failed.

use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use async_trait::async_trait;
use forge::auth::UnixTimestamp;
use forge::http::{HeaderValue, Request, header};
use forge::security::{Permission, RbacPolicy};
use forge::tenancy::{
    BearerDenied, BearerSessionStore, MembershipStore, TenantContext, resolve_bearer,
};

/// Authorizes requests to a tenant-scoped JSON resource.
#[async_trait]
pub trait ApiTenantAccess: Send + Sync {
    /// The tenant context that allows `request` to use `permission`.
    async fn authorize(
        &self,
        request: &Request,
        permission: &Permission,
    ) -> Result<TenantContext, BearerDenied>;
}

/// Authorizes requests to a global JSON resource.
#[async_trait]
pub trait ApiGlobalAccess: Send + Sync {
    /// Allows `request` to use `permission`, or refuses it.
    async fn authorize(
        &self,
        request: &Request,
        permission: &Permission,
    ) -> Result<(), BearerDenied>;
}

/// Refuses every request (`403`): the fail-closed default of every generated
/// JSON resource until the application decides who may use it.
#[derive(Clone, Copy, Debug, Default)]
pub struct DenyAll;

#[async_trait]
impl ApiTenantAccess for DenyAll {
    async fn authorize(&self, _: &Request, _: &Permission) -> Result<TenantContext, BearerDenied> {
        Err(BearerDenied::Forbidden)
    }
}

#[async_trait]
impl ApiGlobalAccess for DenyAll {
    async fn authorize(&self, _: &Request, _: &Permission) -> Result<(), BearerDenied> {
        Err(BearerDenied::Forbidden)
    }
}

/// Bearer token, membership and RBAC authorization for tenant-scoped JSON
/// routes.
///
/// For each request: exactly one `Authorization: Bearer` header must carry a
/// live token, the principal must have an active membership in the tenant
/// the token was issued for, and the policy must grant one of its roles the
/// permission. Anything else is refused.
#[derive(Clone)]
pub struct BearerTenantAccess {
    sessions: Arc<dyn BearerSessionStore>,
    memberships: Arc<dyn MembershipStore>,
    policy: RbacPolicy,
}

impl BearerTenantAccess {
    /// `policy` grants permissions to tenant roles; an empty policy denies
    /// everything.
    #[must_use]
    pub fn new(
        sessions: Arc<dyn BearerSessionStore>,
        memberships: Arc<dyn MembershipStore>,
        policy: RbacPolicy,
    ) -> Self {
        Self {
            sessions,
            memberships,
            policy,
        }
    }
}

#[async_trait]
impl ApiTenantAccess for BearerTenantAccess {
    async fn authorize(
        &self,
        request: &Request,
        permission: &Permission,
    ) -> Result<TenantContext, BearerDenied> {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|elapsed| UnixTimestamp::from_secs(elapsed.as_secs()))
            .map_err(|_| BearerDenied::Unavailable)?;
        let authorization = request
            .headers()
            .get_all(header::AUTHORIZATION)
            .iter()
            .map(HeaderValue::as_bytes);
        resolve_bearer(self.sessions.as_ref(), authorization, now)
            .await?
            .authorize(now, self.memberships.as_ref(), &self.policy, permission)
            .await
    }
}
